func TestFormatNamespaces(t *testing.T) {
	for _, value := range []any{nil, true, "local", []any{"local", 1}} {
		_, err := FormatNamespaces(value)
		require.Error(t, err)
	}
	namespaces, err := FormatNamespaces([]any{})
	require.NoError(t, err)
	require.Empty(t, namespaces)
}

